// === Tab: mySketch ===
// #WCCChallenge: Downward Spiral 🌀

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
}

let v = 10;
let steps = 20;
let e = 1;
let ne = 1;

function draw() {
	background(250);
	// space between rotations
	v = noise(frameCount / 60 / 30, 2.5) * 15 + 15;
	// space scaling when further from center
	e = noise(frameCount / 60 / 5) * 0.8 + 1;
	ne = noise(frameCount / 60 / 7, 1.5) * 0.8 + 1;
	// steps per rotation
	steps = noise(frameCount / 60 / 120, 3.5) * 10 + 20;
	// kind of spiral phase
	let gth = frameCount / 60 * TWO_PI / 120;

	strokeWeight(1.5);
	fill(0, 0, 0, 50);

	push();
	translate(width / 2, height / 2);
	for (let i=0;i < TWO_PI * 50;i += (Math.max(0.001, Math.abs(TWO_PI / steps)) || 1)) {
		// two points on spirals with different scaling
		let r = v * pow(i, 1/e);
		let x = r * cos(i);
		let y = r * sin(i);

		let ni = i + TWO_PI/steps;
		let rr = v * pow(ni, 1/ne);
		let nx = rr * cos(ni);
		let ny = rr * sin(ni);

		// rotate points around 0 by gth
		let rx = cos(gth) * x - sin(gth) * y;
		let ry = sin(gth) * x + cos(gth) * y;

		let rnx = cos(gth) * nx - sin(gth) * ny;
		let rny = sin(gth) * nx + cos(gth) * ny;

		// stroke(250, 200, 100)
		// line(rx, ry, rnx, rny);			
		stroke(0);
		rect(rx, ry, rnx - rx, rny - ry);
		rect(-rx, -ry, -rnx + rx, -rny + ry);
	}
	pop();

	/*
	stroke(255, 0, 255);
	fill(255, 0, 255);
	textAlign(LEFT, TOP);
	text(`${e.toFixed(4)} ${ne.toFixed(4)} ${v.toFixed(4)} ${steps.toFixed(2)}`, 0, 0);
	*/
}
